      {
        stable_step_id = "quest:other_areas:26:step-022",
        order = 22,
        source_orders = { 7, 18 },
        comparison = "corroborated",
        agreed_fields = { "action" },
        conflicting_fields = {  },
        action = "note",
        entities = { "Pirate's Chart", "Brigand's Chart", "Zaldon" },
        zones = {  },
        grid_coordinates = {  },
        bg_instruction = "As of the November 10th, 2021 Version Update, the chance to receive an item is increased when a bigger fish is traded. Fish size is noted on each fish when looking at it in your inventory.",
        ffxiclopedia_instruction = "It is wellknown that if you store either a Pirate's Chart or a Brigand's Chart in your inventory and continue trading Zaldon marlins that you will eventually receive the other chart from him. What is not known is whether this affects the drop rate of the second chart. Obviously, the game must check your inventory in order to know that you are holding the chart. Thus, there are two possibilities:",
        route_ready = false,
      },
      {
        stable_step_id = "quest:other_areas:26:step-023",
        order = 23,
        source_orders = { 0, 19 },
        comparison = "single-source",
        agreed_fields = {  },
        conflicting_fields = {  },
        action = "note",
        entities = {  },
        zones = {  },
        grid_coordinates = {  },
        bg_instruction = "",
        ffxiclopedia_instruction = "The game checks your inventory, sees that you are holding a chart, then gives you the other one. In this case, the drop rate of the chart when holding should be equal to the combined drop rates for both charts when not holding.",
        route_ready = false,
      },
      {
        stable_step_id = "quest:other_areas:26:step-024",
        order = 24,
        source_orders = { 0, 20 },
        comparison = "single-source",
        agreed_fields = {  },
        conflicting_fields = {  },
        action = "note",
        entities = {  },
        zones = {  },
        grid_coordinates = {  },
        bg_instruction = "",
        ffxiclopedia_instruction = "The game checks your inventory, sees that you are holding a chart, then drops the chart without informing you. In other words, the drop rates for the charts are independent of each other. In this case, the drop rate when holding a chart will be equal to the drop rate of the chart when not holding.",
        route_ready = false,
      },
      {
        stable_step_id = "quest:other_areas:26:step-025",
        order = 25,
        source_orders = { 0, 21 },
        comparison = "single-source",
        agreed_fields = {  },
        conflicting_fields = {  },
        action = "note",
        entities = {  },
        zones = {  },
        grid_coordinates = {  },
        bg_instruction = "",
        ffxiclopedia_instruction = "Clearly, the first case is preferable. It would mean that players can hold on to a chart without fear that they are silently missing out on obtaining more. The way to determine which is happening is to also keep track of drop rates when holding charts. A preliminary study posted on Titanictus.com showed that the drop rate when holding is equal to the drop rate when not holding, meaning the second case is how the...",
        route_ready = false,
